    modulus = 1
    for p in primes:
        modulus *= p
    # Count coprime squares up to N
    X = int(math.isqrt(n_limit))
    coprime_m_count = 0
    for m in range(1, X+1):
        # m^2 <= n_limit automatically, check gcd(m, modulus) = 1
        # gcd(1, modulus)=1 ensures at least one toggle
        if math.gcd(m, modulus) == 1:
            coprime_m_count += 1
    # Enforce difficulty: many toggles but not trivial extremes
    if coprime_m_count >= 40 and coprime_m_count <= X - 5:
        return {'n_limit': n_limit, 'modulus': modulus}
# Fallback deterministic hard instance if random fails
n_limit = 50000
modulus = 2*3*5*7  # 210
return {'n_limit': n_limit, 'modulus': modulus}

